CREATE TABLE "MovieView" ("id" SERIAL PRIMARY KEY, "userId" INTEGER NOT NULL, "movieId" INTEGER NOT NULL, "viewedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MovieView_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "MovieView_movieId_fkey" FOREIGN KEY ("movieId") REFERENCES "Movie"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "MovieView_userId_viewedAt_idx" ON "MovieView"("userId", "viewedAt");
